import i18n from "i18next";
import { initReactI18next } from "react-i18next";

const resources = {};

const savedLanguage = localStorage.getItem("appLanguage") || "en";

i18n.use(initReactI18next).init({
  resources,
  lng: savedLanguage,
  fallbackLng: "en",
  interpolation: { escapeValue: false },
});
export default i18n;

